style.css:
@-moz-document domain("youtube.com") {
/* =========================
   COLOR PALETTE
========================= */
:root{
  --pink-main: #FFB6C9;
  --pink-soft: #FFE2EA;
  --pink-hover: #FFA9C0;
  --cream: #FFF8F2;
  --offwhite: #FFFCFA;
  --brown: #B68A72;
  --brown-dark: #7D5A50;
  --sparkle: #FFD8E4;
}

/* =========================
   MAIN BACKGROUND
========================= */
html, body, ytd-app {
    background: var(--cream) !important;
}

/* =========================
   TOP BAR
========================= */
#masthead-container,
ytd-masthead {
    background: var(--pink-soft) !important;
    border-bottom: 2px solid var(--pink-main) !important;
}

/* =========================
   SIDEBAR
========================= */
tp-yt-app-drawer,
#guide-content {
    background: #FFF4F7 !important;
}

/* =========================
   TEXT
========================= */
* {
    color: var(--brown-dark) !important;
    font-family: "Poppins", "Quicksand", sans-serif !important;
}

/* =========================
   SEARCH BAR
========================= */
#search {
    background: white !important;
    border: 2px solid var(--pink-main) !important;
    border-radius: 14px !important;
}

#search-icon-legacy {
    background: var(--pink-main) !important;
    border-radius: 0 14px 14px 0 !important;
}

/* =========================
   BUTTONS
========================= */
button,
yt-button-shape button {
    background: var(--pink-main) !important;
    color: white !important;
    border-radius: 12px !important;
    border: none !important;
}

/* =========================
   VIDEO CARDS
========================= */
ytd-rich-item-renderer,
ytd-video-renderer {
    background: var(--offwhite) !important;
    border: 2px solid var(--pink-soft) !important;
    border-radius: 18px !important;
    padding: 10px !important;
    transition: 0.25s ease !important;
}

ytd-rich-item-renderer:hover,
ytd-video-renderer:hover {
    transform: scale(1.02);
    border-color: var(--pink-main) !important;
    box-shadow: 0 0 18px rgba(255,182,201,0.4) !important;
}

/* =========================
   THUMBNAILS
========================= */
img {
    border-radius: 14px !important;
}

/* =========================
   PROGRESS BAR
========================= */
.ytp-play-progress {
    background: var(--pink-hover) !important;
}

/* =========================
   HEARTS + BOWS + SPARKLES
========================= */

/* Heart beside logo */
#logo::after {
    content: " ♡";
    color: var(--pink-main) !important;
    font-size: 18px;
}

/* Bow beside search */
#search-form::before {
    content: "?";
    margin-right: 8px;
    font-size: 18px;
}

/* Sparkle on hover */
ytd-rich-item-renderer:hover::after,
ytd-video-renderer:hover::after {
    content: " ✧ ✦";
    position: absolute;
    top: 8px;
    right: 8px;
    color: var(--pink-main);
    font-size: 14px;
}
}
